code.java:
class Solution {
    public int singleNumber(int[] nums) {
        int answer = 0;
        for (int value : nums) answer ^= value;
        return answer;
    }
}

code.kotlin:
class Solution {
    fun singleNumber(nums: IntArray): Int {
        var answer = 0
        for (value in nums) answer = answer xor value
        return answer
    }
}

